namespace BobbyBoi;
enum WorldEventKind { Fishing,BuildHouse,Treasure,AdoptWolf,Clone,Climb,CursorPrank,Dragon,HouseVisit,Prison,Casino,Portal,Herobrine,Earthquake,FakeUpdate,AdoptCreeper,YouTube,Ufo,Cave }
[Flags]enum ActivityResource { None=0, Movement=1, Animation=2, Cursor=4, Battle=8 }
record ActivitySpec(WorldEventKind Kind,int Priority,float Cooldown,float EstimatedSeconds,ActivityResource Resources);
sealed class WorldState {
 public bool Automatic{get;set;}=true;public bool Fishing{get;set;}=true;public bool Houses{get;set;}=true;public bool Chests{get;set;}=true;public bool Companions{get;set;}=true;public bool Clones{get;set;}=true;public bool Climbing{get;set;}=true;public bool Dragons{get;set;}=true;
 public bool Expansion{get;set;}=true;public bool Creepy{get;set;}=true;public bool Pranks{get;set;}=true;public bool PetCreeper{get;set;}public bool CreeperSitting{get;set;}public bool PerformanceMode{get;set;}public int CompanionLimit{get;set;}=2;public Dictionary<string,DateTimeOffset> LastEvents{get;set;}=[];public string LastStory{get;set;}="MINING DIRT AT 3AM";public int Subscribers{get;set;}
 public bool AllowCursor{get;set;}public bool Debug{get;set;}public int EventInterval{get;set;}=70;
 public bool HasHouse{get;set;}public float HouseX{get;set;}public float HouseY{get;set;}public int HouseBlocks{get;set;}public int HouseVariant{get;set;}
 public bool WolfAdopted{get;set;}public string WolfName{get;set;}="Biscuit";public string WolfMode{get;set;}="Follow";
 public Dictionary<string,int> StoredItems{get;set;}=[];public Dictionary<string,int> Counters{get;set;}=[];public HashSet<string> Achievements{get;set;}=[];
 public bool Enabled(WorldEventKind kind)=>kind switch{WorldEventKind.Fishing=>Fishing,WorldEventKind.BuildHouse or WorldEventKind.HouseVisit=>Houses,WorldEventKind.Treasure=>Chests,WorldEventKind.AdoptWolf=>Companions,WorldEventKind.Clone=>Clones,WorldEventKind.Climb=>Climbing,WorldEventKind.CursorPrank=>AllowCursor,WorldEventKind.Dragon=>Dragons,WorldEventKind.Herobrine=>Expansion&&Creepy,WorldEventKind.Prison or WorldEventKind.Earthquake or WorldEventKind.FakeUpdate or WorldEventKind.Ufo=>Expansion&&Pranks,WorldEventKind.Casino or WorldEventKind.Portal or WorldEventKind.AdoptCreeper or WorldEventKind.YouTube or WorldEventKind.Cave=>Expansion,_=>false};
 public void Normalize(){LastStory=string.IsNullOrWhiteSpace(LastStory)?"MINING DIRT AT 3AM":LastStory[..Math.Min(70,LastStory.Length)];LastEvents??=[];CompanionLimit=Math.Clamp(CompanionLimit,1,2);Subscribers=Math.Clamp(Subscribers,0,999999);if(CompanionLimit==1&&WolfAdopted)PetCreeper=false;EventInterval=Math.Clamp(EventInterval,30,300);HouseVariant=Math.Clamp(HouseVariant,0,3);HouseBlocks=Math.Clamp(HouseBlocks,0,200);if(!float.IsFinite(HouseX))HouseX=0;if(!float.IsFinite(HouseY))HouseY=0;WolfName=string.IsNullOrWhiteSpace(WolfName)?"Biscuit":WolfName[..Math.Min(24,WolfName.Length)];StoredItems??=[];Counters??=[];Achievements??=[];}
}
sealed class WorldActivity {
 public readonly Guid Id=Guid.NewGuid();public readonly ActivitySpec Spec;public float Age,Wait=5,PhaseAge;public int Phase;public string Loot="Dirt",Stage="preparing";public bool Heavy,Manual;public System.Numerics.Vector2 Start,Target;
 public WorldActivity(ActivitySpec spec,bool manual){Spec=spec;Manual=manual;}
}
sealed class WorldEventDirector {
 public static readonly ActivitySpec[] Specs=[new(WorldEventKind.Fishing,30,65,18,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.BuildHouse,30,240,18,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Treasure,40,100,10,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.AdoptWolf,25,300,7,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Clone,25,150,4,ActivityResource.Animation),new(WorldEventKind.Climb,40,90,18,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.CursorPrank,45,300,4,ActivityResource.Movement|ActivityResource.Animation|ActivityResource.Cursor),new(WorldEventKind.Dragon,90,600,36,ActivityResource.Movement|ActivityResource.Animation|ActivityResource.Battle),new(WorldEventKind.HouseVisit,20,75,10,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Prison,60,480,22,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Casino,40,180,12,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Portal,45,360,18,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Herobrine,35,600,6,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Earthquake,55,360,6,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.FakeUpdate,35,300,14,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.AdoptCreeper,25,300,6,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.YouTube,30,180,12,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Ufo,60,600,18,ActivityResource.Movement|ActivityResource.Animation),new(WorldEventKind.Cave,30,150,14,ActivityResource.Movement|ActivityResource.Animation)];
 readonly Dictionary<WorldEventKind,float> last=[];readonly List<WorldEventKind> pending=[];readonly Random random;float now,next=35;
 WorldState? activeState;public WorldActivity? Active{get;private set;}public bool Busy=>Active!=null;public int Queued=>pending.Count;
 public WorldEventDirector(int? seed=null){random=seed.HasValue?new Random(seed.Value):new Random();}
 public void Queue(WorldEventKind kind){if(Active?.Spec.Kind!=kind&&!pending.Contains(kind))pending.Add(kind);}
 public WorldActivity? Tick(float dt,WorldState state,bool safe,bool expeditionSoon,Func<WorldEventKind,bool> eligible){now+=dt;if(Active!=null){Active.Age+=dt;Active.PhaseAge+=dt;return null;}if(!safe)return null;pending.RemoveAll(k=>!state.Enabled(k)||!eligible(k));
  if(pending.Count==0&&state.Automatic&&now>=next&&!expeditionSoon){next=now+state.EventInterval+random.Next(-10,21);var candidates=Specs.Where(s=>state.Enabled(s.Kind)&&eligible(s.Kind)&&(!state.LastEvents.TryGetValue(s.Kind.ToString(),out var saved)||(DateTimeOffset.UtcNow-saved).TotalSeconds>=s.Cooldown)&&now-(last.TryGetValue(s.Kind,out var t)?t:(s.Kind==WorldEventKind.Dragon?-0: -600))>=s.Cooldown).ToArray();if(candidates.Length>0){var s=candidates[random.Next(candidates.Length)];pending.Add(s.Kind);}}
  var kind=pending.OrderByDescending(k=>Specs.Single(s=>s.Kind==k).Priority).FirstOrDefault(k=>state.Enabled(k)&&eligible(k), (WorldEventKind)(-1));if((int)kind<0)return null;pending.Remove(kind);activeState=state;Active=new WorldActivity(Specs.Single(s=>s.Kind==kind),true);return Active;
 }
 public WorldActivity? Pause(){var a=Active;Active=null;return a;}
 public void Resume(WorldActivity a){if(Active!=null)throw new InvalidOperationException("Activity already active");Active=a;}
 public void Finish(){if(Active!=null){last[Active.Spec.Kind]=now;if(Active.Spec.Kind>=WorldEventKind.Prison&&activeState!=null)activeState.LastEvents[Active.Spec.Kind.ToString()]=DateTimeOffset.UtcNow;Active=null;}}
 public void Cancel(){Finish();}
 public void Clear(){Finish();pending.Clear();}
 public static void Test(){var d=new WorldEventDirector(7);var s=new WorldState{Automatic=false};d.Queue(WorldEventKind.Fishing);d.Queue(WorldEventKind.BuildHouse);var a=d.Tick(.1f,s,true,false,_=>true);if(a==null||!d.Busy)throw new Exception("World event not started");d.Queue(WorldEventKind.Dragon);if(d.Tick(1,s,true,false,_=>true)!=null||d.Active!=a)throw new Exception("Overlapping activity");d.Finish();if(d.Tick(.1f,s,true,false,_=>true)?.Spec.Kind!=WorldEventKind.Dragon)throw new Exception("Activity priority");d.Clear();s.AllowCursor=false;d.Queue(WorldEventKind.CursorPrank);if(d.Tick(1,s,true,false,_=>true)!=null)throw new Exception("Disabled real cursor event started");}
}
